def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.access_count = {}

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            self.access_count[key] += 1
            return self.cache[key]

        def __setitem__(self, key, value):
            if key in self.cache:
                self.access_count[key] += 1
            else:
                if len(self.cache) >= self.maxsize:
                    self._evict()
                self.cache[key] = value
                self.access_count[key] = 1

        def _evict(self):
            min_count = min(self.access_count.values())
            for key in list(self.access_count.keys()):
                if self.access_count[key] == min_count:
                    del self.cache[key]
                    del self.access_count[key]
                    break

    def decorator(func):
        cache = LFUCache(maxsize, typed)
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else (args, kwargs)
            return cache[key]
        return wrapper

    return decorator
