def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity dictionary must contain 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("Files list must be a list")

    for file in files:
        if not isinstance(file, dict):
            raise ValueError("Each file entry in the fixity dictionary must be a dictionary")

        if 'path' not in file:
            raise ValueError("Each file entry must contain 'path' key")

        if 'hash' not in file:
            raise ValueError("Each file entry must contain 'hash' key")

        if 'algorithm' not in file:
            raise ValueError("Each file entry must contain 'algorithm' key")

        if file['path'] not in manifest_files:
            raise ValueError(f"File path '{file['path']}' is not listed in the manifest")

        if file['algorithm'] not in ['md5', 'sha1', 'sha256', 'sha512']:
            raise ValueError(f"Unsupported hash algorithm '{file['algorithm']}'")

        if not isinstance(file['hash'], str):
            raise ValueError("Hash value must be a string")

    print("Fixity block is valid and consistent with the manifest.")
