def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorb_expression(expr):
        if isinstance(expr, tuple):
            if expr[0] == '&':
                if expr[1] == expr[2]:
                    return expr[1]
                elif expr[1] == '~' and expr[2] == expr[3]:
                    return expr[2]
            elif expr[0] == '|':
                if expr[1] == expr[2]:
                    return expr[1]
                elif expr[1] == '~' and expr[2] == expr[3]:
                    return expr[3]
        return expr

    return [absorb_expression(arg) for arg in args]
```

