import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        raise TypeError("commands must be a list of strings")

    command = commands + args

    try:
        output = subprocess.check_output(command, cwd=cwd, stderr=subprocess.STDOUT if not hide_stderr else subprocess.PIPE,
                                         env=env, universal_newlines=True)
        if verbose:
            print(output)
    except subprocess.CalledProcessError as e:
        msg = "couldn't run command\n{}".format(command)
        if verbose:
            print(msg)
        raise ProgramError(msg)
