            raise ValueError("yaml_file argument must be supplied")

        with yaml_file.open() as f:
            data = yaml.load(f)

        # Assuming a predefined schema for validation
        schema = {
            "type": "object",
            "properties": {
                "required_field": {"type": "string"},
                "another_required_field": {"type": "integer"}
            },
            "required": ["required_field", "another_required_field"]
        }

        try:
            jsonschema.validate(data, schema)
        except jsonschema.exceptions.ValidationError as ve:
            raise IRValidatorException(f"Validation failed: {ve.message}")

        return data
